  function caseList(){const q=query.toLowerCase();return rows.filter(r=>tab!=='surgery'||r.kind==='surgery').filter(r=>(deleted||closed||r.status!=='closed')&&[r.patient?.name,r.body.quickPatient?.chartNumber,r.body.title,r.body.location,r.body.anesthesiaSheet?.operation].join(' ').toLowerCase().includes(q)).map(r=>`<button class="cl-case ${r.id===selected?'selected':''}" data-cl-case="${esc(r.id)}"><b>${esc(r.patient?.name||'환자')}</b><span>${r.patient_id?'등록 환자':'빠른 진료'}${r.body.quickPatient?.chartNumber?' · 차트 '+esc(r.body.quickPatient.chartNumber):''}</span><span>${tab==='surgery'?esc(r.body.anesthesiaSheet?.operation||r.body.title||'수술명 미입력'):kindNames[r.kind]+' · '+esc(r.body.location||r.body.title)}</span><span>${r.body.deleted?'삭제됨':statusNames[r.status]}${tab==='surgery'?' · '+fmtDate(r.created_at||r.createdAt):' · 미완료 '+handoffTasks(r.body.tasks||[]).length+'개'}</span></button>`).join('')||'<p>'+ (tab==='surgery'?'마취기록이 없습니다. 새 마취 기록에서 환자를 선택하거나 직접 입력하세요.':'조회된 진료 건이 없습니다.')+'</p>';}
