   box.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-med-remove')){const i=Number(b.dataset.medRemove);if(editing===i){f.querySelector('[data-cl-error]').textContent='수정 중인 약물은 입력 비우기를 누른 뒤 제거해주세요.';return;}queue.splice(i,1);if(editing>i)editing--;f.elements.confirm.checked=false;paint();f.dispatchEvent(new Event('input',{bubbles:true}));return;}if(f.elements.drug.value.trim()){f.querySelector('[data-cl-error]').textContent='입력 중인 약물을 먼저 목록에 담아주세요.';return;}editing=Number(b.dataset.medEdit);const q=queue[editing];for(const [k,v] of Object.entries(q.medication))if(f.elements[k]){if(k==='prn')f.elements[k].checked=v;else f.elements[k].value=v;}f.elements.doseBasis.value=q.medication.calculation?'kg':'total';f.elements.dose.value=q.medication.calculation?.dosePerKg??q.medication.dose;f.elements.instruction.value=q.instruction;f.querySelector('[data-med-add]').textContent='목록의 약물 수정 적용';f.elements.confirm.checked=false;f.dispatchEvent(new Event('input',{bubbles:true}));};
   return {add(items){if(editing>=0||['drug','dose','strength'].some(k=>f.elements[k].value.trim()))throw Error('개별 입력 중인 약물을 먼저 목록에 담거나 비워주세요.');if(queue.length+items.length>30)throw Error('한 번에 30개까지 입력할 수 있습니다.');queue.push(...items);f.elements.confirm.checked=false;paint();}};
