  function roomCard(r){const c=r.patientCase,body=c?.body;return '<article class="cc-room '+(c?'cc-occupied':'cc-vacant')+'" data-room-card="'+esc(r.id)+'" data-room-layout="'+esc(JSON.stringify([r.name,r.kind,r.care_state,c?.id]))+'" data-room-fingerprint="'+esc(roomFingerprint(r))+'"><button class="cl-room '+(c?'occupied':'vacant')+'" data-cl-action="room-open" data-id="'+esc(r.id)+'"><span class="cl-room-top"><b>'+esc(r.name)+'</b></span>'+(c?'<span class="cl-room-identity"><strong>'+esc(c.patient?.name||'환자 기록 확인 필요')+'</strong><span class="cl-patient-demographics">'+esc(wardPatientSummary(c))+'</span></span>':'<strong>환자 등록하기</strong>')+(body?'<span class="cl-room-complaint">'+esc(body.careTeam?.chiefComplaint||'주호소 미입력')+'</span>'+roomTaskSummary(c)+roomSummary(body):'')+'</button>'+(body?'<details class="cl-room-details" '+(!boardCompact?'open':'')+'><summary>환자 정보·측정값</summary>'+careTeamMarkup(body.careTeam,true,false)+wardVitalCards(body,true)+(body.latestMonitoring?'<div class="cl-room-monitor">'+monitoringMarkup(body.latestMonitoring,true,true)+'</div>':'')+'</details>'+(saveNoticeCase===c.id&&saveNotice?'<p class="cl-local-save" role="status">'+esc(saveNotice)+'</p>':'')+(a.can?.('records.edit')!==false&&c.status!=='closed'?'<div class="cl-round-action">'+button('ward-round-open','측정·관찰 기록','data-id="'+esc(c.id)+'"')+'</div>':''):'')+'</article>';}
  function careTeamMarkup(team={},compact=false,includeComplaint=true){if(compact&&!team.chiefComplaint&&!team.veterinarianName&&!team.technicianName)return '';return '<span class="cl-care-team '+(compact?'cl-care-team-compact':'')+'">'+(includeComplaint?'<span class="cl-care-cc" title="'+esc(team.chiefComplaint||'미입력')+'"><b>주호소</b><span>'+esc(team.chiefComplaint||'미입력')+'</span></span>':'')+'<span class="cl-care-staff"><span><b>담당 수의사</b><span>'+esc(team.veterinarianName||'미지정')+'</span></span><span><b>담당 테크니션</b><span>'+esc(team.technicianName||'미지정')+'</span></span></span></span>';}
