  function roomSummary(body){const due=wardDue(body.tasks||[]),m=body.latestMonitoring;return ((body.orderChanges||[]).some(c=>!c.ackAt&&c.mode!=='copy')?'<span class="cl-alert">변경 지시 미확인 '+body.orderChanges.filter(c=>!c.ackAt&&c.mode!=='copy').length+'건</span>':'')+(body.wardPlan?'<span class="cl-precautions">'+Object.entries(wardPrecautionLabels).filter(([k])=>body.wardPlan.checks?.[k]==='present').map(([k,l])=>'<span class="cl-alert">'+l+' 있음'+(k==='fasting'&&body.wardPlan.fastUntil?' · '+fmtDate(body.wardPlan.fastUntil)+'까지':'')+'</span>').join('')+'</span>':'')+roomMissingInfo(body)+(m?'<span class="cl-room-monitor">'+Object.entries(monitoringLabels).filter(([k])=>monitoringTone(k,m[k])==='abnormal').map(([k,l])=>'<span class="cl-monitor-abnormal">'+esc(l)+' '+esc(monitoringOptions[k].find(x=>x[0]===m[k])?.[1]||m[k])+'</span>').join('')+'</span>':'')+ '<span class="cl-room-alerts">'+['temperature','heartRate','respiratoryRate'].map(k=>{const v=wardVitalStatus(body,k);return v.abnormal||v.stale?'<span class="cl-stale">'+esc(vitalLabels[k])+' '+esc(v.value)+' · '+(v.abnormal?'보고 기준 밖':'재확인 필요')+'</span>':'';}).join('')+'</span>'; }
