   if(action==='room-assign'||action==='room-attach'){const attaching=action==='room-attach';const candidates=rows.filter(c=>c.kind==='admission'&&c.status!=='closed'&&!c.body.deleted&&!c.room_id&&c.body.species===(room?.kind==='cat'?'cat':'dog'));const free=rooms.filter(r=>!r.patientCase&&(r.kind==='cat'?'cat':'dog')===item?.body.species);modal('기존 입원 기록 연결',attaching?select('caseId','입원실 미지정 환자',[['','선택'],...candidates.map(c=>[c.id,c.patient.name+' · '+(c.body.quickPatient?.chartNumber||c.id.slice(-6))])]):select('roomId','빈 입원실',[['','선택'],...free.map(r=>[r.id,r.name])]),async f=>{const c=attaching?candidates.find(c=>c.id===f.elements.caseId.value):item,r=attaching?room:free.find(r=>r.id===f.elements.roomId.value);if(!c||!r)throw Error('연결할 환자와 빈 입원실을 선택해주세요.');await api('/cases/'+c.id+'/events','POST',{revision:c.revision,requestKey:f.dataset.clRequestKey,kind:'room.assign',data:{roomId:r.id,roomRevision:r.revision}});selected=c.id;selectedRoom=r.id;});return;}
