   catch(e){if(current(context)&&active()?.id===id){if(saved){detail.canManage=false;detail.canRecord=false;saveNotice='확인은 저장됐습니다. 최신 화면 조회에 실패해 새로고침이 필요합니다.';}else{error='확인 저장을 확인하지 못했습니다. 같은 버튼으로 재시도하거나 새로고침해주세요. '+(e.message||'');}render();}}
