  function safety(){const source=carry?.rows?carry:null;if(!source)return `<section class="cl-empty"><h4>계산한 처방을 불러오세요</h4><p>처방 일괄 계산 결과에서 ‘처방 안전성 검토’를 누르면 환자·종·체중·제품 함량과 함께 가져옵니다.</p>${button('calc','처방 일괄 계산 열기','data-kind="batch"')}</section>`;report=reviewPrescription({...source,checks});return `<section class="cl-card"><h4>${esc(source.patient?.name||'환자 미연결')} · ${source.rows.length}개 처방 검토</h4><p>${esc(report.summary)}</p><p class="cl-help">${esc(report.coverage)}</p><div class="cl-findings">${report.findings.map(f=>`<article class="cl-finding-${f.severity}"><b>${({warning:'주의',review:'검토',missing:'미확인'})[f.severity]}</b><span>${esc(f.text)}</span>${f.source?`<a href="${f.source}" target="_blank" rel="noopener">근거</a>`:''}</article>`).join('')}</div><details><summary>원처방·검사 범위</summary><pre>${esc(source.rows.map(r=>g.PracticeRxWorkflow?.line(r)||r.drug).join('\n'))}</pre><p>규칙 버전 ${VERSION} · 미지원 성분 ${esc(report.unknown.join(', ')||'없음')} · 용량 범위 자동 판정 없음</p></details><div class="cl-actions">${button('calc','계산기로 돌아가기','data-kind="batch"')}${medical()?button('save-safety','의료진 검토 기록'):''}</div></section>`;}
  let protocolQuery='',protocolQuick='all',protocolPrefScope='',protocolFavorites=[],protocolRecent=[];
  const protocolPrefKey=()=>a.preferencesIdentity?.()?'carestep.protocol.shortcuts:'+a.preferencesIdentity():'';
  function restoreProtocolPrefs(){const key=protocolPrefKey();if(protocolPrefScope===key)return;protocolPrefScope=key;protocolFavorites=[];protocolRecent=[];protocolQuick='all';try{const v=JSON.parse(localStorage.getItem(key)||'{}');const ids=x=>Array.isArray(x)?x.filter(id=>typeof id==='string'&&id.length<160).slice(0,100):[];protocolFavorites=ids(v.favorites);protocolRecent=ids(v.recent).slice(0,20);const state=JSON.parse(sessionStorage.getItem(key+':view')||'{}');protocolQuery=typeof state.query==='string'?state.query.slice(0,200):'';protocolCategoryFilter=protocolCategories.some(([id])=>id===state.category)?state.category:'all';protocolSpeciesFilter=['all','dog','cat','unknown'].includes(state.species)?state.species:'all';protocolSource=state.source==='hospital'?'hospital':'common';protocolPage=Number.isInteger(state.page)&&state.page>0?state.page:1;protocolQuick=['all','favorites','recent'].includes(state.quick)?state.quick:'all';}catch{}}
  function saveProtocolPrefs(){const key=protocolPrefKey();if(!key)return;try{localStorage.setItem(key,JSON.stringify({favorites:protocolFavorites,recent:protocolRecent}));sessionStorage.setItem(key+':view',JSON.stringify({query:protocolQuery,category:protocolCategoryFilter,species:protocolSpeciesFilter,source:protocolSource,page:protocolPage,quick:protocolQuick}));}catch{}}
  function visitProtocol(id,source=protocolSource){const key=source+':'+id;protocolRecent=[key,...protocolRecent.filter(x=>x!==key)].slice(0,20);saveProtocolPrefs();}

  function protocolLibrary(){restoreProtocolPrefs();return '<section class="cl-protocol-browser" aria-label="진료 프로토콜 목록"><div class="cl-protocol-filters"><label>진료 프로토콜 검색<input type="search" data-protocol-query value="'+esc(protocolQuery)+'" placeholder="질환·증상·제목"></label><label>진료 분야<select data-protocol-category>'+protocolCategories.map(([id,label])=>'<option value="'+id+'" '+(id===protocolCategoryFilter?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>동물종<select data-protocol-species>'+[['all','전체'],['dog','개'],['cat','고양이'],['unknown','동물종 미지정']].map(([id,label])=>'<option value="'+id+'" '+(id===protocolSpeciesFilter?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div><div class="cl-protocol-sources" role="group" aria-label="자료 구분">'+[['common','공통 자료'],['hospital','병원 자료']].map(([id,label])=>'<button type="button" data-protocol-source="'+id+'" aria-pressed="'+(protocolSource===id)+'">'+label+' <span data-protocol-count="'+id+'"></span></button>').join('')+'</div><div class="cl-protocol-shortcuts" aria-label="자주 보는 자료">'+[['all','전체'],['favorites','즐겨찾기'],['recent','최근 열람']].map(([id,label])=>'<button type="button" data-protocol-quick="'+id+'" aria-pressed="'+(protocolQuick===id)+'">'+label+'</button>').join('')+'</div><div data-protocol-library>'+protocolList()+'</div></section>'+(a.medical()?'<details class="cl-card cl-protocol-create"><summary>병원 프로토콜 만들기</summary>'+button('protocol-new','빈 문서로 시작')+'<p>근거가 연결된 초안에서 시작</p><div class="cl-actions">'+(g.ClinicalProtocolStarters||[]).map(t=>button('protocol-starter',esc(t.body.title),'data-id="'+esc(t.id)+'"')).join('')+'</div></details><details class="cl-card cl-protocol-patient"><summary>환자에게 적용 · '+esc(active()?.patient?.name||'환자 선택')+'</summary>'+(active()?identityCard(active()):'')+'<div data-protocol-patients></div></details>':'');}
  function protocolList(){
   const state=protocolCache.state(protocolSource),items=protocolQuick==='all'?state.items:state.items.filter(p=>(protocolQuick==='favorites'?protocolFavorites:protocolRecent).includes(protocolSource+':'+p.id)),ordered=protocolQuick==='recent'?[...items].sort((a,b)=>protocolRecent.indexOf(protocolSource+':'+a.id)-protocolRecent.indexOf(protocolSource+':'+b.id)):items,list=protocolSelection(ordered,{query:protocolQuery,category:protocolCategoryFilter,species:protocolSpeciesFilter,page:protocolPage,size:12,preserveOrder:protocolQuick==='recent'});if(state.at!==null)protocolPage=list.page;
   const label=protocolSource==='common'?'공통 자료':'병원 자료',notice=state.error?'<div class="cl-protocol-notice" role="alert">'+esc(state.error)+(state.items.length?' 마지막으로 불러온 목록입니다.':'')+button('protocol-retry','다시 시도','data-id="'+protocolSource+'"')+'</div>':state.pending?'<p role="status" class="cl-protocol-notice">'+(state.at!==null?'목록 업데이트 중…':label+'를 불러오는 중…')+'</p>':'';
   const hint=protocolSource==='common'?'HQ에서 공개한 자료 · 선택하면 본문과 근거를 확인합니다.':'병원 검토본 · 공개한 자료만 환자에게 적용할 수 있습니다.';
   if(state.at===null&&!state.items.length&&(state.pending||state.error))return notice;
   const cards=list.items.map(p=>{const category=protocolCategories.find(([id])=>id===protocolCategory(p))[1],species=({dog:'개',cat:'고양이',both:'개·고양이 공통'})[protocolSpecies(p)]||'동물종 미지정';const content='<span class="cl-protocol-meta">'+category+' · '+species+(protocolSource==='hospital'?' · '+esc(statusNames[p.status]||p.status):'')+'</span><strong>'+esc(protocolShortTitle(p))+'</strong>';const key=protocolSource+':'+p.id,favorite='<button type="button" class="cl-protocol-favorite" data-protocol-favorite="'+esc(p.id)+'" aria-label="'+esc(protocolShortTitle(p))+' 즐겨찾기" aria-pressed="'+protocolFavorites.includes(key)+'">'+(protocolFavorites.includes(key)?'★':'☆')+'</button>';return '<div class="cl-protocol-entry">'+(protocolSource==='common'?'<button type="button" class="cl-protocol-card" data-cl-action="common-protocol" data-id="'+esc(p.id)+'" aria-label="'+esc(p.title)+'">'+content+'</button>':'<button type="button" class="cl-protocol-card" data-cl-action="hospital-protocol" data-id="'+esc(p.id)+'" aria-label="'+esc(p.title)+'">'+content+'</button>')+favorite+'</div>';}).join('');
   return notice+'<p class="cl-help">'+hint+'</p><p class="cl-protocol-result" role="status">'+label+' · '+list.total+'개'+(protocolSpeciesFilter==='dog'||protocolSpeciesFilter==='cat'?' · 개·고양이 공통 자료 포함':'')+'</p><div class="cl-protocol-grid">'+(cards||'<p class="cl-empty">'+(protocolQuick!=='all'?(protocolQuick==='favorites'?'별표를 눌러 자주 쓰는 자료를 추가하세요.':'최근 열람한 자료가 없습니다.') :state.items.length?'검색 조건에 맞는 자료가 없습니다. 다른 검색어나 분류를 선택해주세요.':protocolSource==='common'?'공개된 공통 자료가 없습니다.':'등록된 병원 자료가 없습니다.')+'</p>')+'</div>'+(list.pages>1?'<nav class="cl-protocol-pages" aria-label="프로토콜 목록 페이지"><button type="button" data-protocol-page="'+(list.page-1)+'" '+(list.page===1?'disabled':'')+'>이전</button><span>'+list.page+' / '+list.pages+'</span><button type="button" data-protocol-page="'+(list.page+1)+'" '+(list.page===list.pages?'disabled':'')+'>다음</button></nav>':'');
  }
  function paintProtocolList(){const box=root.querySelector('[data-protocol-library]');if(!box)return;box.innerHTML=protocolList();box.querySelectorAll('[data-protocol-favorite]').forEach(b=>b.onclick=()=>{const key=protocolSource+':'+b.dataset.protocolFavorite;protocolFavorites=protocolFavorites.includes(key)?protocolFavorites.filter(x=>x!==key):[key,...protocolFavorites].slice(0,100);saveProtocolPrefs();paintProtocolList();box.querySelector('[data-protocol-favorite="'+CSS.escape(b.dataset.protocolFavorite)+'"]')?.focus({preventScroll:true});});root.querySelectorAll('[data-protocol-count]').forEach(el=>{const state=protocolCache.state(el.dataset.protocolCount);el.textContent=state.at!==null?String(state.items.length):state.error?'조회 실패':'…';});root.querySelectorAll('[data-protocol-source]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.protocolSource===protocolSource)));box.querySelectorAll('[data-cl-action]').forEach(b=>b.onclick=()=>void action(b));box.querySelectorAll('[data-protocol-page]').forEach(b=>b.onclick=()=>{protocolPage=Number(b.dataset.protocolPage);saveProtocolPrefs();paintProtocolList();box.querySelector('button,summary')?.focus({preventScroll:true});box.scrollIntoView({block:'nearest'});});}
  function bindProtocolLibrary(){if(tab!=='protocols')return;root.querySelectorAll('[data-protocol-quick]').forEach(b=>b.onclick=()=>{protocolQuick=b.dataset.protocolQuick;protocolPage=1;saveProtocolPrefs();root.querySelectorAll('[data-protocol-quick]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));paintProtocolList();});root.querySelector('[data-protocol-query]')?.addEventListener('input',e=>{protocolQuery=e.target.value;protocolPage=1;saveProtocolPrefs();paintProtocolList();});root.querySelector('[data-protocol-category]')?.addEventListener('change',e=>{protocolCategoryFilter=e.target.value;protocolPage=1;saveProtocolPrefs();paintProtocolList();});root.querySelector('[data-protocol-species]')?.addEventListener('change',e=>{protocolSpeciesFilter=e.target.value;protocolPage=1;saveProtocolPrefs();paintProtocolList();});root.querySelectorAll('[data-protocol-source]').forEach(b=>b.onclick=()=>{protocolSource=b.dataset.protocolSource;protocolPage=1;saveProtocolPrefs();paintProtocolList();});root.querySelector('.cl-protocol-patient')?.addEventListener('toggle',e=>{if(e.target.open)void protocolPatients();});paintProtocolPatients();paintProtocolList();}
  const vitalLabels={temperature:'체온 · °C',heartRate:'심박수 · 회/분',respiratoryRate:'호흡수 · 회/분',spo2:'SpO₂ · %',etco2:'ETCO₂ · mmHg',systolic:'수축기 혈압 · mmHg',diastolic:'이완기 혈압 · mmHg',meanPressure:'평균 혈압 · mmHg',fluidInML:'수액 투입량 · mL',urineML:'소변량 · mL',foodGrams:'급여량 · g',weightKG:'체중 · kg'};
