  function identityCard(item){return `<section class="cl-identity"><div><b>${item.patient_id?'등록 환자 연결됨':'빠른 진료 · 보호자 등록 없음'}</b><p>${esc(item.body.title)}${item.body.quickPatient?.chartNumber?' · 차트 '+esc(item.body.quickPatient.chartNumber):''} · ${fmtDate(item.created_at)} · 식별 ${esc(item.id.slice(-6))}</p>${careTeamMarkup(item.body.careTeam)}</div><div class="cl-actions">${medical()&&item.status!=='closed'&&!item.body.deleted?button('care-team','주호소·담당자 수정'):''}${medical()&&item.status!=='closed'?button('weight',item.body.weight?'체중 수정':'체중 입력'):''}${!item.patient_id&&!item.body.deleted&&medical()?button('link-patient','등록 환자와 연결'):''}${medical()?(item.body.deleted?button('restore-case','진료 건 복원'):button('delete-case','진료 건 삭제','class="cl-danger"')):''}</div></section>`;}
